#!/bin/bash
#Example 1: Concatenating 2 string variables
first="Kali";
second="Linux";
combined="$first$second";
echo "$combined";

#Example 2: Concatenating strings with a space
greeting="Hello,";
name="User!";
message="$greeting $name";
echo "$message";

#Example 3: Concatenating integers as strings
a=10;
b=20;
result="$a$b";
echo "$result";

#Example 4: Concatenation with echo
string="Bash Scripting";
echo "We like, $string!"
